import type { EnvConfig } from '#lib/types/env-config.type.js';
import type { EnvSettingOverride } from '#lib/types/env-settings-override.type.js';
import staticConfig from '../../../../static/config.json' with { type: 'json' };

// Shape of static/config.json (schemaVersion 2), generated by `just docs config` in the Arcane repo.
type RuntimeEnvConfig = {
	env: string;
	description?: string;
	defaultValue?: string;
	deprecated?: boolean;
};

type RuntimeSetting = {
	env: string;
	key: string;
	description?: string;
	default?: string;
	requires?: string;
	sensitive?: boolean;
	deprecated?: boolean;
	note?: string;
};

type RuntimeDocsConfig = {
	envConfig?: RuntimeEnvConfig[];
	settings?: RuntimeSetting[];
};

const LOCAL_CONFIG = staticConfig as RuntimeDocsConfig;

// Most config.Config fields have no description upstream yet. Show nothing rather than a
// placeholder; descriptions appear once the Arcane config struct gains `description` tags.
export const envConfig: EnvConfig[] = (LOCAL_CONFIG.envConfig ?? []).map((item) => ({
	name: item.env,
	description: item.description ?? '',
	defaultValue: item.defaultValue ?? '',
	deprecated: item.deprecated
}));

export const envSettingsOverrides: EnvSettingOverride[] = (LOCAL_CONFIG.settings ?? []).map(
	(item) => ({
		env: item.env,
		settingKey: item.key,
		description: item.description ?? '',
		requires: item.requires,
		defaultValue: item.default,
		sensitive: item.sensitive,
		deprecated: item.deprecated,
		note: item.note
	})
);
